const totalTickets =
$('Total Tickets').first().json.total;

const totalErrores =
$('Errores Sistema').first().json.errores;

const categorias =
$('Tickets por Categoría').all();

const prioridades =
$('Prioridades').all();

let categoriasHTML = '';

for (const item of categorias) {

  categoriasHTML += `
    <tr>
      <td>${item.json.categoria}</td>
      <td>${item.json.cantidad}</td>
    </tr>
  `;

}

let prioridadesHTML = '';

for (const item of prioridades) {

  let color = '#22c55e';

  if (item.json.prioridad === 'ALTA') {
    color = '#ef4444';
  }

  if (item.json.prioridad === 'MEDIA') {
    color = '#f59e0b';
  }

  prioridadesHTML += `
    <tr>
      <td style="color:${color};font-weight:bold;">
        ${item.json.prioridad}
      </td>
      <td>${item.json.cantidad}</td>
    </tr>
  `;

}

